"""
ext_config.py — the registry for the October 2026 "everything" additions to Basketball Savant.

Every new card bar is one entry in EXT_METRICS, every new panel one entry in EXT_PANELS. The
entry carries what the page needs (label, group, sub-group, unit, hatching threshold, direction,
era) and what the explainer needs (what / formula / source / sample), so a stat can't ship
without its explanation. tools/savant-explainers/add_ext_stats.py writes both into the page;
the connector reads the page's CFG and EXPL, as it does for every other stat.

Fields (as savant_config.METRICS, plus):
  fam      the data family (decides which pass computes it and which lane refreshes it)
  win      True if recomputed for the L10 / L25 / L75 windows, False if season-only
  first    first season it exists (`since` is the era tier's first season, for the page's gate)
  ext      always True here. These stats ship beside the archive, not in it (savant-data.json
           is near GitHub's 100 MB limit): ext_files.py writes public/savant-ext/, which the
           page fetches for the season a reader opens, for finished seasons and the season in
           progress alike.

Lanes (who refreshes the season in progress without the Mac):
  cloud    rebuilt from ESPN box scores / play-by-play / Basketball-Reference after every slate
  nba      the NBA's tracking, hustle, Synergy and matchup tables: the Mac's upload when it is
           awake, else the public mirror (gabriel1200/site_Data) for the families it covers
"""

NBA = "NBA.com stats (stats.nba.com)"
TRK = f"{NBA} player tracking"
HUS = f"{NBA} hustle stats"
SYN = f"{NBA} Synergy play types"
MAT = f"{NBA} matchup data"
AWS = f"{NBA} Inside the Game (NBA x AWS)"
BRF = "Basketball Reference"
ESP = "ESPN play-by-play"
POSS = "POSS = possessions he was on the floor for."
P75 = lambda x: f"{x} ÷ POSS × 75. {POSS}"  # noqa: E731
CLOUD_NOTE = "Refreshed in the cloud after every slate."
NBA_NOTE = ("In season it moves when the NBA's tables are pulled (the Mac's upload, or the public "
            "mirror of NBA tracking when the Mac is off).")
SEASON_ONLY = "Season totals only: the NBA doesn't split this table by last N games."


TIER_SINCE = {1: "1979-80", 2: "1996-97", 3: "2013-14", 4: "2016-17"}   # = savant_config.TIER_SINCE


def M(key, label, group, sub, unit, thr, lower, fam, win, first, what, formula, source, sample,
      layer="ingredient"):
    """`first` is the first season the data really exists. The page gates bars by era tier and
    the connector by `since`, and the two must agree on the four existing tiers, so a stat that
    starts mid-tier (matchups in 2017-18, the AWS stats in 2025-26) is filed under the tier it
    falls in: seasons before `first` simply have no value, and the explainer names `first`."""
    if fam == "combine":
        tier = 1                      # measurements: shown for any season a player was measured
    else:
        tier = 1 if first < "1996" else 2 if first < "2013" else 3 if first < "2016" else 4
    if fam == "combine":
        win = True                    # a measurement is the same number in every window
    return dict(key=key, label=label, group=group, sub=sub, layer=layer, unit=unit, thr=thr,
                lower=lower, tier=tier, since=TIER_SINCE[tier], first=first, fam=fam, win=win,
                ext=True, what=what, formula=formula, source=source, sample=sample)


